// Repeated, host-paced observation/update/feedback in one resident graph.
#define main inherited_readout_entry
#include "readout_bench.cpp"
#undef main
#include "hardware_device_impl.h"
#include "dma_config_mem_rw.h"
#include "engine/dma.h"
class ResidentDriver final:public akida::HardwareDriver {
 public:LabDriver io;
 void read(uint32_t a,void*p,size_t n)const override{io.read(a,p,n);}
 void write(uint32_t a,const void*p,size_t n)override{io.write(a,p,n);}
 const char*desc()const override{return "one resident native adaptive memory / external observations";}
 uint32_t scratch_memory()const override{return io.scratch_memory();}uint32_t scratch_size()const override{return io.scratch_size();}uint32_t top_level_reg()const override{return io.top_level_reg();}
 uint32_t akida_visible_memory()const override{return 0;}uint32_t akida_visible_memory_size()const override{return 0;}
};
int main(int argc,char**argv){
 std::unique_ptr<ResidentDriver>d;akida::HardwareDevicePtr dev;std::vector<uint8_t>program;
 try{
  need(argc==6,"cpu/native fixture arm epochs output");std::string mode=argv[1],f=argv[2],arm=argv[3],out=argv[5];int epochs=std::stoi(argv[4]);need((mode=="cpu"||mode=="native")&&(arm=="native"||arm=="baseline"||arm=="frozen"||arm=="disconnected")&&(epochs==1||epochs==2||epochs==4||epochs==12),"frozen arguments");
  constexpr int n=256,u=8;int count=0,cap=arm=="baseline"?24:8;auto stem=f+"/"+arm+"_e"+std::to_string(epochs);auto plan=load<int32_t>(stem+".plan");count=int(plan.size()/5);need(count>=16+29*epochs&&count<=16+29*epochs+8,"bounded selector probe");auto supplied=load<uint8_t>(stem+".inputs"),codes=load<uint8_t>(f+"/codes");auto initial=load<uint32_t>(f+"/"+arm+".ram");auto old=load<int32_t>(f+"/old");need(plan.size()==size_t(count*5)&&supplied.size()==size_t(count*n)&&initial.size()==98&&codes.size()==u*n,"fixture shapes");
  auto pack=[&](const uint8_t*x){std::vector<uint32_t>b(8);for(int k=0;k<n;k++)b[k/32]|=uint32_t(x[k])<<(k%32);return b;};
  auto decode=[&](const std::vector<int32_t>&p){std::vector<uint8_t>y(n);for(int j=0;j<u;j++)if(p[j]>24)for(int k=0;k<n;k++)y[k]|=codes[j*n+k];return y;};
  auto advance=[&](CPU&c,const uint8_t*x,int label){auto before=c.ram;auto p=c.forward(pack(x),std::max(0,label),label>=0);if(label<0)for(auto v:p)c.rot=(c.rot+mix(v))&31;if(label>=0)for(int j=0;j<u;j++){int b=2+j*c.stride;bool changed=!std::equal(before.begin()+b+4,before.begin()+b+c.stride,c.ram.begin()+b+4);if(changed)c.ram[b+3]=(uint32_t(std::min(p[j],cap))<<16)|(c.ram[b+3]&65535);}return decode(p);};
  CPU ref(n,u,32,u,initial);std::vector<uint8_t>want,expected_inputs;std::vector<uint32_t>expected_states;
  for(int i=0;i<count;i++){int src=plan[5*i+3],label=plan[5*i+2];need(src<i&&src>=-1,"backward dependency");const uint8_t*x=src>=0?want.data()+src*n:supplied.data()+i*n;need(std::equal(x,x+n,supplied.begin()+i*n),"independent packed CPU feedback inputs");auto y=advance(ref,x,label);expected_inputs.insert(expected_inputs.end(),x,x+n);want.insert(want.end(),y.begin(),y.end());expected_states.insert(expected_states.end(),ref.ram.begin(),ref.ram.end());}
  if(mode=="cpu"){
   std::vector<uint8_t>task_y,task_x;auto table=old;
   for(int i=0;i<count;i++){int src=plan[5*i+3],label=plan[5*i+2];const uint8_t*x=src>=0?task_y.data()+src*n:supplied.data()+i*n;int s=-1;for(int k=0;k<n&&s<0;k++)if(x[k]){int hits=0,who=-1;for(int j=0;j<u;j++)if(codes[j*n+k]){hits++;who=j;}if(hits==1)s=who;}need(s>=0,"task CPU recognizes state");std::vector<uint8_t>y(codes.begin()+table[s]*n,codes.begin()+(table[s]+1)*n);task_x.insert(task_x.end(),x,x+n);task_y.insert(task_y.end(),y.begin(),y.end());if(label>=0)table[s]=label;}
   constexpr int repeats=400;uint64_t checksum=0;auto t=ns(),ct=cpu_ns();
   for(int r=0;r<repeats;r++){CPU c(n,u,32,u,initial);std::vector<uint8_t>yy;yy.reserve(count*n);for(int i=0;i<count;i++){int src=plan[5*i+3],label=plan[5*i+2];const uint8_t*x=src>=0?yy.data()+src*n:supplied.data()+i*n;auto y=advance(c,x,label);for(auto v:y)checksum=checksum*1099511628211ULL+v;yy.insert(yy.end(),y.begin(),y.end());}need(c.ram==ref.ram,"exact CPU repeat final memory");}
   auto exact_wall=ns()-t,exact_cpu=cpu_ns()-ct;std::vector<int32_t>owner(n,-1);for(int k=0;k<n;k++){int hits=0,who=-1;for(int j=0;j<u;j++)if(codes[j*n+k]){hits++;who=j;}if(hits==1)owner[k]=who;}
   t=ns();ct=cpu_ns();for(int r=0;r<repeats;r++){auto tab=old;std::vector<uint8_t>yy;yy.reserve(count*n);for(int i=0;i<count;i++){int src=plan[5*i+3],label=plan[5*i+2];const uint8_t*x=src>=0?yy.data()+src*n:supplied.data()+i*n;int s=-1;for(int k=0;k<n&&s<0;k++)if(x[k]&&owner[k]>=0)s=owner[k];need(s>=0,"CPU state");const uint8_t*y=codes.data()+tab[s]*n;for(int k=0;k<n;k++)checksum=checksum*1099511628211ULL+y[k];yy.insert(yy.end(),y,y+n);if(label>=0)tab[s]=label;}}
   auto table_wall=ns()-t,table_cpu=cpu_ns()-ct;std::vector<int32_t>ids;for(int i=0;i<count;i++)ids.push_back(i);dump(out+".scores",want);dump(out+".inputs",expected_inputs);dump(out+".states",expected_states);dump(out+".state_ids",ids);dump(out+".ram",ref.ram);dump(out+".table_scores",task_y);dump(out+".table_inputs",task_x);
   std::cout<<"{\"status\":\"PASS\",\"mode\":\"cpu\",\"events\":"<<count<<",\"repeats\":"<<repeats<<",\"exact_wall_ns\":"<<exact_wall<<",\"exact_cpu_ns\":"<<exact_cpu<<",\"table_wall_ns\":"<<table_wall<<",\"table_cpu_ns\":"<<table_cpu<<",\"checksum\":"<<checksum<<"}\n";return 0;
  }
  d=std::make_unique<ResidentDriver>();d->io.dma_read_min=128;dev=akida::HardwareDevice::create(d.get());program=load<uint8_t>(f+"/"+arm+".bin");auto info=dev->program(program.data(),program.size());need(info.number_of_passes()==1&&info.can_learn()&&info.input_is_dense()&&info.output_is_dense()&&info.activation_enabled()&&info.output_bits()==1,"one resident dense learner/decoder");dev->toggle_learn(true);bool learning=true;auto impl=static_cast<akida::HardwareDeviceImpl*>(dev.get());need(dev->set_batch_size(64,false)==64,"64 output buffers preserve carry across observations");impl->pipeline(false);
  auto capture=[&](){if(!learning)dev->toggle_learn(true);std::vector<uint32_t>v(dev->learn_mem_size());dev->learn_mem(v.data());if(!learning){dev->toggle_learn(false);impl->pipeline(false);}return v;};need(capture()==initial,"initial SRAM exact");dump(out+".initial.ram",initial);
  auto fixed=[&](const char*tag){auto p=load<uint32_t>(f+"/"+arm+".fixed"),q=p;akida::dma::dma_config_read(q.data()+2,q.size()-2,q.data(),impl->dma_config(),impl->mem(),d.get(),true);dump(out+".fixed."+tag,q);need(q==p,"fixed decoder memory unchanged");};fixed("initial");
  auto external=dev->scratch_alloc(n);std::vector<uint32_t>descriptors,addresses,observed_states,input_addresses;std::vector<int32_t>state_ids;std::vector<uint8_t>ys,xs;std::vector<int64_t>quiet,latency;
  auto snapshot=[&](int i){auto ram=capture();observed_states.insert(observed_states.end(),ram.begin(),ram.end());state_ids.push_back(i);dump(out+".states",observed_states);dump(out+".state_ids",state_ids);need(std::equal(ram.begin(),ram.end(),expected_states.begin()+i*98),"full captured SRAM differs from independent packed CPU");};
  auto enqueue=[&](int i){int src=plan[5*i+3],label=plan[5*i+2];uint32_t in=src<0?external:addresses[src]+32;if(src<0)d->write(external,supplied.data()+i*n,n);need(in>=LabDriver::RAM+256&&uint64_t(in)+n<=uint64_t(LabDriver::RAM)+LabDriver::SIZE,"native SRAM input bound");need(dev->enqueue(in,label>=0?&label:nullptr),"resident event enqueue");auto desc=d->io.last_descriptor;need(desc[1]==in&&((desc[8]>>16)&1023)==uint32_t(label>=0?label+1:0),"input and teacher descriptor fields");if(src>=0)need(desc[7]!=addresses[src],"carry output not overwritten in same slot");input_addresses.push_back(in);addresses.push_back(desc[7]);descriptors.insert(descriptors.end(),desc.begin(),desc.end());};
  auto fetch=[&](int i,bool immediate){akida::TensorUniquePtr y;auto until=Clock::now()+std::chrono::seconds(2);if(immediate)y=dev->fetch();else while(!(y=dev->fetch()))need(Clock::now()<until,"serial completion bound");need(y&&y->type()==akida::TensorType::uint8&&y->size()==n,"resident returned code");auto p=y->data<uint8_t>();ys.insert(ys.end(),p,p+n);std::vector<uint8_t>x(n);d->read(input_addresses[i],x.data(),n);xs.insert(xs.end(),x.begin(),x.end());std::vector<uint32_t>packet(72);d->read(addresses[i],packet.data(),288);dump(out+".packet"+std::to_string(i),packet);dump(out+".scores",ys);dump(out+".inputs",xs);need(std::equal(p,p+n,want.begin()+i*n),"resident output differs from packed CPU");need(std::equal(x.begin(),x.end(),expected_inputs.begin()+i*n),"observed input differs from sealed native dependency");};
  for(int i=0;i<count;){
   if(i==16&&arm=="frozen"){learning=false;dev->toggle_learn(false);impl->pipeline(false);}
   if(plan[5*i]==5){int start=i,epoch=plan[5*i+1];d->io.hold_queue();for(int j=0;j<16;j++){need(plan[5*i]==5&&plan[5*i+1]==epoch&&plan[5*i+2]==-1,"bounded unlabelled burst");enqueue(i++);}auto target=descriptors[(i-1)*16]>>16;auto r0=d->io.reads,w0=d->io.writes;auto t0=ns(),c0=cpu_ns();d->io.release_queue();std::this_thread::sleep_for(std::chrono::milliseconds(5));auto t1=ns(),c1=cpu_ns();auto reads=d->io.reads-r0,writes=d->io.writes-w0;auto status=d->io.read32(LabDriver::REG+0x28010);quiet.insert(quiet.end(),{int64_t(epoch),int64_t(start),t0,t1,c1-c0,int64_t(reads),int64_t(writes),int64_t(target),int64_t(status)});dump(out+".quiet",quiet);need(reads==0&&writes==1&&(status>>16)==target,"quiet burst complete at first wake");for(int j=start;j<i;j++)fetch(j,true);snapshot(i-1);
   }else{auto t=ns();d->io.hold_queue();enqueue(i);d->io.release_queue();fetch(i,false);latency.push_back(ns()-t);snapshot(i);i++;}
  }
  dump(out+".descriptors",descriptors);dump(out+".output_addresses",addresses);dump(out+".input_addresses",input_addresses);dump(out+".latency_ns",latency);auto final=capture();dump(out+".ram",final);need(final==ref.ram,"resident final learning SRAM");fixed("final");dev->scratch_free(external);dev->unprogram();std::cout<<"{\"status\":\"PASS\",\"mode\":\"native\",\"events\":"<<count<<",\"epochs\":"<<epochs<<",\"program_calls\":1,\"learning_parameter_resets\":0,\"weight_restore_calls\":0,\"host_state_seeds\":1,\"cleanup\":\"unprogrammed\"}\n";
 }catch(const std::exception&e){if(d&&d->io.held)try{d->io.release_queue();}catch(...){}if(dev)try{dev->unprogram();}catch(...){}std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}
}
